    "dashboardSso.resumen": {
        parameters: {
            query: {
                periodo: string;
                unidad_administrativa_id?: number | null;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        exito: boolean;
                        /** @constant */
                        mensaje: "Resumen del dashboard SSO calculado exitosamente.";
                        datos: {
                            periodo: string;
                            unidad_administrativa_id: number | null;
                            riesgos: {
                                total_activos: string;
                                /**
                                 * @description La clave vacía son los riesgos anteriores a la matriz NTP 330,
                                 *     que tienen el nivel en NULL. Antes salían igual, porque agrupar
                                 *     por null en PHP también da la clave vacía.
                                 */
                                por_nivel_intervencion: number[];
                            };
                            accidentes: {
                                total: number;
                                con_atencion_medica: number;
                                dias_reposo_total: number;
                            };
                            epp: {
                                /**
                                 * @description El catálogo es institucional por naturaleza: un casco existe para
                                 *     toda la institución, no para una dirección. Por eso el bloque
                                 *     declara alcance institucional aunque las entregas sí filtren.
                                 */
                                equipos_activos: number;
                                entregas_periodo: number;
                            };
                            indicadores_reactivos: unknown[];
                            indicadores_proactivos: unknown[];
                            cumplimiento: {
                                total: number;
                                cumple: number;
                                no_cumple: number;
                                en_proceso: number;
                                no_registrado: number;
                            };
                            psicosocial: {
                                campanias_activas: string;
                                total_respuestas: number;
                                riesgo_alto: number;
                            };
                            assist: {
                                campanias_activas: string;
                                total_respuestas: number;
                                riesgo_alto: number;
                                /**
                                 * @description «No reporta consumo» es quien contestó que no ha consumido
                                 *     ninguna sustancia: el mapa de niveles llega vacío. Se compara
                                 *     como jsonb porque el tipo `json` de PostgreSQL no tiene operador
                                 *     de igualdad, y contra las dos formas de lo vacío porque el mapa
                                 *     lo arma PHP: un array asociativo sin claves se serializa `[]`,
                                 *     no `{}`. Quedarse con una sola contaba cero.
                                 */
                                sin_consumo_reportado: number;
                            };
                            programa_drogas: {
                                total: number;
                                ejecutada: number;
                                en_proceso: number;
                                no_ejecutada: number;
                                pendiente: number;
                            };
                            ausentismo: {
                                total_permisos: number;
                                servidores_afectados: number;
                                /**
                                 * @description La jornada vive en `JornadaLaboral`; aquí se presenta con dos
                                 *     decimales y no con cuatro, que es lo que pide un consolidado.
                                 */
                                total_dias: number;
                            };
                            alcances: {
                                riesgos: {
                                    alcance: string;
                                    nota: null;
                                };
                                accidentes: {
                                    alcance: string;
                                    nota: null;
                                };
                                epp: {
                                    alcance: string;
                                    nota: string | null;
                                };
                                cumplimiento: {
                                    alcance: string;
                                    /** @constant */
                                    nota: "La normativa legal aplica a toda la institución, no por unidad.";
                                };
                                psicosocial: {
                                    alcance: string;
                                    nota: null;
                                };
                                assist: {
                                    alcance: string;
                                    nota: null;
                                };
                                programa_drogas: {
                                    alcance: string;
                                    /** @constant */
                                    nota: "Las actividades del programa de prevención no se registran por unidad.";
                                };
                                ausentismo: {
                                    alcance: string;
                                    nota: null;
                                };
                            };
                        };
                        meta: null;
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            422: components["responses"]["ValidationException"];
        };
    };
